<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute, useRouter } from 'vue-router'
import { useSessionStore } from '@/stores/session'
import { useGigs } from '@/composables/useGigs'
import { ApiError, asApiError } from '@/api/client'
import { basisInput, checkLabels, commissionOrderAllowed, getCatalogue, getEntries, getNotifications, getRanking, gigStatuses, gigTitle, isCommissionTerms, listCommercialSupply, rankingDate, type Catalogue, type CommissionEntry, type CommercialSupply, type GigChecks, type GigKind, type GigRecord, type PublicRanking } from '@/api/modules/gigs'
import { listTrade, money, type TradeRecord } from '@/api/modules/trade'
import { validSupplyId, type MediaType } from '@/api/modules/supply'
import WorkspaceNav from '@/components/WorkspaceNav.vue'
import ApiErrorAlert from '@/components/ApiErrorAlert.vue'
import SupplyUpload from '@/components/SupplyUpload.vue'
import GigRecordPanel from '@/components/GigRecordPanel.vue'
import GigRuleForm from '@/components/GigRuleForm.vue'
import ContractText from '@/components/ContractText.vue'
import type { TextValue } from '@/api/modules/contracts'
const savedText=(v:unknown)=>v as TextValue
import '@/styles/supply.css'
import '@/styles/trade.css'
import '@/styles/gigs.css'
const route=useRoute(),router=useRouter(),session=useSessionStore()
const section=computed(()=>String(route.params.section||'catalogue')),formPage=computed(()=>route.name==='gigs-new'),reviewPage=computed(()=>route.name==='gigs-review'),targetId=computed(()=>String(route.params.recordId||''))
const independent=computed(()=>reviewPage.value||section.value==='rules'||section.value==='rankings')
const kindMap:Record<string,GigKind>={catalogue:'GIG',requests:'GIG',offers:'OFFER',relations:'RELATION',rules:'RULE',commissions:'COMMISSION',rankings:'RANKING'},kind=computed(()=>kindMap[section.value]||'GIG')
const titles:Record<string,string>={catalogue:'商单需求目录',requests:'商单需求目录',offers:'客户确认提案与履约关联',relations:'直接合作确认与历史',commissions:'订单佣金计提记录',rules:'商单规则独立审核',rankings:'生成与查看榜单快照'}
const pageTitle=computed(()=>formPage.value?{requests:'登记商单需求',offers:'提交商单服务提案',relations:'发起直接MCN合作',rules:'登记商单规则版本'}[section.value]:reviewPage.value?{requests:'商单需求独立审核',offers:'服务提案独立审核',rules:'商单规则独立审核'}[section.value]:titles[section.value])
const gallery=computed(()=>formPage.value?{requests:'WEB-19-02',offers:'WEB-20-01',relations:'WEB-21-01-v2',rules:'WEB-22-01'}[section.value]:reviewPage.value?{requests:'WEB-19-03',offers:'WEB-20-02-v2',rules:'WEB-22-02-v3'}[section.value]:{catalogue:'WEB-19-01-v2',requests:'WEB-19-01-v2',offers:'WEB-20-03',relations:'WEB-21-02',commissions:'WEB-21-03-v3',rules:'WEB-22-02-v3',rankings:'WEB-22-03'}[section.value])
const canOwn=computed(()=>!!session.selected&&session.selected.membership.current_status==='ACTIVE'&&session.selected.membership.roles.includes('OWNER')&&!['SUSPENDED','CLOSED'].includes(session.selected.party.current_status))
const canMcn=computed(()=>canOwn.value&&session.selected?.party.capabilities.some(c=>c.code==='MCN'&&c.current_status==='ACTIVE'))
const context=()=>({token:session.token,accountId:session.account?.id||'',partyId:independent.value?null:session.selectedId,revision:session.revision,scope:route.fullPath})
const ui=useGigs(context),{rows,detail,nextCursor,error,notice,pending,busy,securityRevision,conflictRevision,retryAt}=ui
const catalogue=ref<Catalogue|null>(null),specs=ref<TradeRecord[]>([]),orders=ref<TradeRecord[]>([]),quotes=ref<TradeRecord[]>([]),relations=ref<GigRecord[]>([]),avatars=ref<CommercialSupply[]>([]),consents=ref<CommercialSupply[]>([]),entries=ref<CommissionEntry[]>([]),ranking=ref<PublicRanking|null>(null),notifications=ref<{id:string;record_id:string;event_code:string}[]>([])
const initializing=ref(true),pageLoading=ref(false),now=ref(Date.now()),openId=ref(''),decision=ref(''),reason=ref(''),confirmed=ref(false),changed=ref(false),newDecision=ref(false),relationDecision=ref(''),relationReason=ref(''),actionReason=ref(''),orderId=ref(''),rankingRuleId=ref(''),asOf=ref(''),proofAsset=ref('')
const checks=reactive<GigChecks>({identity_verified:false,authority_verified:false,materials_reviewed:false,content_reviewed:false,marking_reviewed:false})
const requestForm=reactive({title:'',brief:'',rule:'',category:'',territory:'',until:'',proofs:[] as {code:string;asset_id:string}[]})
const offerForm=reactive({gig:'',spec:'',avatar:'',consent:'',relation:'',platform:'',mcn:'',terms:'',ranking:'',assets:[] as string[]})
const relationForm=reactive({artist:'',from:'',until:'',exclusive:'',platform:'',mcn:'',terms:'',assets:[] as string[]})
const locked=computed(()=>busy.value||!!pending.value||now.value<retryAt.value||changed.value&&!newDecision.value)
const formLocked=computed(()=>locked.value||!independent.value&&!canOwn.value)
const chosenRule=computed(()=>catalogue.value?.rules.find(r=>r.id===requestForm.rule)),chosenCategory=computed(()=>chosenRule.value?.rule.categories.find(c=>c.code===requestForm.category))
const chosenGig=computed(()=>catalogue.value?.items.find(g=>g.id===offerForm.gig)),chosenRelation=computed(()=>relations.value.find(r=>r.id===offerForm.relation&&r.kind==='RELATION'))
const chosenConsent=computed(()=>consents.value.find(c=>c.id===offerForm.consent))
const selectedAvatar=computed(()=>avatars.value.find(a=>a.id===offerForm.avatar))
const eligibleConsents=computed(()=>consents.value.filter(c=>{const v=c.data.consent,g=chosenGig.value;return c.current_status==='APPROVED'&&v&&g&&v.avatar_id===offerForm.avatar&&v.subject_party_id===session.selectedId&&v.features.includes('FACE')&&v.features.includes('VOICE')&&v.purposes.includes('COMMERCIAL')&&v.territories.includes(g.scope.territory)&&Date.parse(v.valid_from)<=now.value&&Date.parse(v.valid_until)>=Date.parse(g.scope.valid_until)}))
const toInstant=(s:string)=>s&&Number.isFinite(Date.parse(s))?new Date(s).toISOString():''
const requestPayload=computed(()=>{if(!chosenRule.value||!chosenCategory.value?.allowed||!requestForm.title.trim()||!requestForm.brief.trim()||!requestForm.territory.trim()||Date.parse(requestForm.until)<=now.value||!toInstant(requestForm.until)||requestForm.proofs.length>30||requestForm.proofs.some(p=>!p.code.trim()||p.code.length>128||!validSupplyId(p.asset_id))||!chosenCategory.value.required_proofs.every(code=>requestForm.proofs.some(p=>p.code===code)))return null;return {title:requestForm.title.trim(),brief:requestForm.brief.trim(),rule_id:requestForm.rule,category:requestForm.category,scope:{purpose:'COMMERCIAL',territory:requestForm.territory.trim(),valid_until:toInstant(requestForm.until)},proofs:requestForm.proofs.map(p=>({...p,code:p.code.trim()}))}})
const offerPayload=computed(()=>{const c={platform_bps:basisInput(offerForm.platform),mcn_bps:basisInput(offerForm.mcn)};const spec=specs.value.find(s=>s.id===offerForm.spec&&s.kind==='SPEC'&&s.current_status==='PUBLISHED'&&s.merchant_party_id===session.selectedId&&s.data.provider_party_id===session.selectedId&&s.data.line_kind!=='LICENSE');if(!chosenGig.value||chosenGig.value.buyer_party_id===session.selectedId||!spec||!selectedAvatar.value||!eligibleConsents.value.some(c=>c.id===offerForm.consent)||!isCommissionTerms(c)||!offerForm.terms.trim()||!['true','false'].includes(offerForm.ranking)||!offerForm.assets.length||offerForm.assets.length>30||!offerForm.relation)return null;if(offerForm.relation==='NONE'){if(c.mcn_bps!==0)return null}else{const r=chosenRelation.value;if(r?.kind!=='RELATION'||r.current_status!=='ACTIVE'||r.counterparty_id!==session.selectedId||Date.parse(r.data.valid_from)>now.value||Date.parse(r.data.valid_until)<=now.value||r.data.commission.platform_bps!==c.platform_bps||r.data.commission.mcn_bps!==c.mcn_bps)return null}return {gig_id:offerForm.gig,spec_id:offerForm.spec,avatar_id:offerForm.avatar,consent_id:offerForm.consent,relation_id:offerForm.relation==='NONE'?null:offerForm.relation,commission:c,terms:offerForm.terms.trim(),ranking_opt_in:offerForm.ranking==='true',evidence_asset_ids:[...offerForm.assets]}})
const relationPayload=computed(()=>{const c={platform_bps:basisInput(relationForm.platform),mcn_bps:basisInput(relationForm.mcn)};if(!canMcn.value||!validSupplyId(relationForm.artist)||relationForm.artist===session.selectedId||!toInstant(relationForm.from)||!toInstant(relationForm.until)||Date.parse(relationForm.from)>=Date.parse(relationForm.until)||Date.parse(relationForm.until)<=now.value||!['true','false'].includes(relationForm.exclusive)||!isCommissionTerms(c)||!relationForm.terms.trim()||!relationForm.assets.length||relationForm.assets.length>30)return null;return {artist_party_id:relationForm.artist,scope:'COMMERCIAL',valid_from:toInstant(relationForm.from),valid_until:toInstant(relationForm.until),exclusive:relationForm.exclusive==='true',commission:c,terms:relationForm.terms.trim(),evidence_asset_ids:[...relationForm.assets]}})
const reviewable=computed(()=>reviewPage.value&&detail.value?.current_status==='IN_REVIEW'&&detail.value.created_by!==session.account?.id&&!session.parties.some(p=>p.membership.current_status==='ACTIVE'&&[detail.value?.owner_party_id,detail.value?.counterparty_id,detail.value?.kind==='OFFER'?detail.value.data.relation?.mcn_party_id:null].includes(p.party.id)))
const reviewValid=computed(()=>reviewable.value&&['APPROVED','REJECTED'].includes(decision.value)&&reason.value.trim()&&(detail.value?.kind==='RULE'||decision.value==='REJECTED'||Object.values(checks).every(Boolean)))
const acceptanceValid=computed(()=>detail.value?.kind==='OFFER'&&detail.value.current_status==='APPROVED'&&detail.value.counterparty_id===session.selectedId&&confirmed.value)
const relationChoices=computed(()=>{const r=detail.value;if(r?.kind!=='RELATION')return [];if(r.current_status==='INVITED')return [...(r.counterparty_id===session.selectedId?['ACCEPT','REJECT']:[]),'END'];return r.current_status==='ACTIVE'?['END']:[]})
let disposed=false,pageTicket=0,timer=0
function reset(){pageTicket++;catalogue.value=null;specs.value=[];orders.value=[];quotes.value=[];relations.value=[];avatars.value=[];consents.value=[];entries.value=[];ranking.value=null;notifications.value=[];openId.value=decision.value=reason.value=relationDecision.value=relationReason.value=actionReason.value=orderId.value=rankingRuleId.value=asOf.value=proofAsset.value='';confirmed.value=changed.value=newDecision.value=false;Object.keys(checks).forEach(k=>checks[k as keyof GigChecks]=false);Object.assign(requestForm,{title:'',brief:'',rule:'',category:'',territory:'',until:'',proofs:[]});Object.assign(offerForm,{gig:'',spec:'',avatar:'',consent:'',relation:'',platform:'',mcn:'',terms:'',ranking:'',assets:[]});Object.assign(relationForm,{artist:'',from:'',until:'',exclusive:'',platform:'',mcn:'',terms:'',assets:[]})}
watch(securityRevision,reset,{flush:'sync'})
watch(conflictRevision,()=>{decision.value=reason.value=relationDecision.value=relationReason.value=actionReason.value='';confirmed.value=false;Object.keys(checks).forEach(k=>checks[k as keyof GigChecks]=false);changed.value=true;newDecision.value=false},{flush:'sync'})
watch(()=>[route.fullPath,session.selectedId,session.revision],()=>{if(!initializing.value)void loadPage()})
watch(()=>requestForm.rule,()=>{requestForm.category='';requestForm.proofs=[]});watch(()=>requestForm.category,()=>{requestForm.proofs=(chosenCategory.value?.required_proofs||[]).map(code=>({code,asset_id:''}))})
watch(()=>[offerForm.gig,offerForm.avatar],()=>{offerForm.consent=''})
function pathFor(r:GigRecord){const s={RULE:'rules',RELATION:'relations',GIG:'requests',OFFER:'offers',COMMISSION:'commissions',RANKING:'rankings'}[r.kind];return `/gigs/${reviewPage.value&&['RULE','GIG','OFFER'].includes(r.kind)?'reviews/':''}${s}/${r.id}`}
async function allTrade(k:'SPEC'|'ORDER'|'QUOTE'){return ui.read('trade-'+k,async(i,s)=>{const out:TradeRecord[]=[],seen=new Set<string>();let cursor:string|null=null;do{const page=await listTrade(i,k,cursor,s);out.push(...page.items);cursor=page.next_cursor;if(cursor&&seen.has(cursor))throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'交易列表没有前进。'});if(cursor)seen.add(cursor)}while(cursor);return out})}
async function loadPage(){if(pending.value)return;const ticket=++pageTicket,current=()=>!disposed&&ticket===pageTicket;pageLoading.value=true;try{
 if(!independent.value&&!canOwn.value&&section.value!=='catalogue'){ui.clear();error.value=new ApiError({status:403,code:'GIG_PARTY_FORBIDDEN',message:'请使用有效负责人身份办理商业合作。'});return}
 if(targetId.value&&!validSupplyId(targetId.value)){error.value=new ApiError({status:400,code:'CLIENT_RECORD_INVALID',message:'请使用完整记录编号。'});return}
 if(section.value==='rankings'){const c=await ui.read('catalogue',getCatalogue);if(current())catalogue.value=c;if(targetId.value){const r=await ui.read('ranking',(i,s)=>getRanking(i,targetId.value,s));if(current())ranking.value=r}return}
 if(section.value==='catalogue'||formPage.value&&['requests','offers'].includes(section.value)){const c=await ui.read('catalogue',getCatalogue);if(!current())return;catalogue.value=c;if(formPage.value&&section.value==='offers'&&route.query.gigId!==undefined){const id=route.query.gigId;if(typeof id==='string'&&validSupplyId(id)&&c?.items.some(g=>g.id===id&&g.buyer_party_id!==session.selectedId))offerForm.gig=id;else notice.value='原商单当前不在可采用目录，可能已暂停、到期或不可由本人提交；请核对原需求。'}}
 if(formPage.value){if(section.value==='offers'){const s=await allTrade('SPEC');if(!current())return;specs.value=s||[];const rs=await ui.loadAll('RELATION');if(!current())return;relations.value=rs||[];const av=await ui.read('avatars',(i,s)=>listCommercialSupply(i,'AVATAR',s));if(!current())return;avatars.value=av||[];const cs=await ui.read('consents',(i,s)=>listCommercialSupply(i,'CONSENT',s));if(current())consents.value=cs||[]}return}
 if(section.value==='commissions'&&!targetId.value){const os=await allTrade('ORDER');if(!current())return;orders.value=(os||[]).filter(o=>o.kind==='ORDER'&&!!o.data.quote.commercial)}
 if(!targetId.value){if(section.value==='catalogue'&&!canOwn.value)return;await ui.loadList(kind.value);if(current()&&section.value==='catalogue'){const n=await ui.read('notifications',getNotifications);if(current())notifications.value=n?.items||[]}return}
 const r=await ui.loadRecord(targetId.value,kind.value);if(!current()||!r)return
 if(r.kind==='COMMISSION'){const e=await ui.read('entries',(i,s)=>getEntries(i,r.id,s));if(current())entries.value=e?.items||[]}
 if(r.kind==='OFFER'&&!reviewPage.value){const qs=await allTrade('QUOTE');if(current())quotes.value=(qs||[]).filter(q=>q.kind==='QUOTE'&&q.data.commercial?.offer_id===r.id)}
 }finally{if(current())pageLoading.value=false}}
function leave(){if(ui.canNavigate())return true;notice.value='原操作结果尚未确认，请先核对并使用原请求编号重试，再切换页面。';return false}
onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave)
function unload(e:BeforeUnloadEvent){if(!ui.canNavigate()){e.preventDefault();e.returnValue=''}}
onMounted(async()=>{timer=window.setInterval(()=>now.value=Date.now(),1000);window.addEventListener('beforeunload',unload);const captured=session.capture();try{await Promise.all([session.loadAccount(),session.loadParties()]);if(!disposed&&session.current(captured)){initializing.value=false;await loadPage()}}catch(e){if(!disposed&&session.current(captured)){ui.clear();error.value=asApiError(e)}}finally{if(!disposed)initializing.value=false}})
onUnmounted(()=>{disposed=true;pageTicket++;window.clearInterval(timer);window.removeEventListener('beforeunload',unload)})
async function create(path:string,body:unknown,resultKind:GigKind,label:string){if(formLocked.value)return;await ui.write({path:'/gigs/'+path,body,resultKind,label},r=>{if(!('kind' in r))return;if(r.kind==='COMMISSION'&&targetId.value===r.id)void ui.read('entries',(i,s)=>getEntries(i,r.id,s),v=>entries.value=v.items);else void router.push(pathFor(r))})}
async function mutate(path:string,body:unknown,label:string){const r=detail.value;if(locked.value||!r)return;await ui.write({path:'/gigs/'+path,body,resultKind:r.kind,targetId:r.id,version:r.object_version,label},()=>{decision.value=reason.value=relationDecision.value=relationReason.value=actionReason.value='';confirmed.value=false;Object.keys(checks).forEach(k=>checks[k as keyof GigChecks]=false)})}
function review(){const r=detail.value;if(!r||!reviewValid.value)return;void mutate(`records/${r.id}/reviews`,{decision:decision.value,reason:reason.value.trim(),checks:r.kind==='RULE'||decision.value==='REJECTED'?null:{...checks}},'提交独立审核')}
function accept(){const r=detail.value;if(r?.kind!=='OFFER'||!acceptanceValid.value)return;void mutate(`offers/${r.id}/acceptance`,{offer_sha256:r.content_sha256},'确认当前完整提案')}
function relationAct(){const r=detail.value;if(r?.kind!=='RELATION'||!relationChoices.value.includes(relationDecision.value)||!relationReason.value.trim())return;void mutate(`relations/${r.id}/decision`,{decision:relationDecision.value,reason:relationReason.value.trim()},'提交直接合作决定')}
function action(){const r=detail.value;if(!r||!actionReason.value.trim())return;if(r.kind==='GIG'&&r.current_status==='PUBLISHED')void mutate(`requests/${r.id}/suspension`,{reason:actionReason.value.trim()},'暂停商单发布');if(r.kind==='RULE'&&r.current_status==='EFFECTIVE')void mutate(`rules/${r.id}/retirement`,{reason:actionReason.value.trim()},'退役此规则版本')}
async function upload(file:File,mediaType:MediaType,proofIndex?:number){if(formLocked.value||!canOwn.value)return;if(section.value==='requests'&&proofIndex===undefined)return;await ui.write({path:`/supply/assets?${new URLSearchParams({purpose:'RIGHTS_EVIDENCE',media_type:mediaType})}`,blob:file,purpose:'RIGHTS_EVIDENCE',mediaType,kind:'ASSET',resultKind:'ASSET',label:'上传商单私有证明'},r=>{if('kind' in r)return;if(section.value==='requests'&&proofIndex!==undefined&&requestForm.proofs[proofIndex])requestForm.proofs[proofIndex].asset_id=r.id;else if(section.value==='offers')offerForm.assets.push(r.id);else relationForm.assets.push(r.id)})}
function calculate(){if(locked.value||!canOwn.value||!commissionOrderAllowed(orderId.value,orders.value,detail.value))return;void create('commissions',{order_id:orderId.value},'COMMISSION','核算当前订单佣金')}
function makeRanking(){const date=asOf.value+'T00:00:00.000Z';if(locked.value||!catalogue.value?.rules.some(r=>r.id===rankingRuleId.value)||!rankingDate(date))return;void create('rankings',{rule_id:rankingRuleId.value,as_of:date},'RANKING','生成实际榜单快照')}
function open(){if(locked.value||!validSupplyId(openId.value))return;void router.push(`/gigs/${reviewPage.value?'reviews/':''}${section.value==='catalogue'?'requests':section.value}/${openId.value}`)}
const privateAssets=computed(()=>{const r=detail.value;if(!r)return [];return r.kind==='GIG'?r.data.proofs.map(p=>({id:p.asset_id,label:p.code})):r.kind==='OFFER'||r.kind==='RELATION'?r.data.evidence_asset_ids.map(id=>({id,label:'私有合作证明'})):[]})
</script>
<template><div class="supply-workspace trade-workspace gigs-workspace" :data-gallery="gallery"><header class="supply-header"><RouterLink to="/workspace" class="supply-brand">晶晶日上</RouterLink><span>运营与合作方工作台</span><div class="account-actions"><span class="account-name">{{session.account?.display_name||'当前账号'}}</span><button @click="session.logout().then(()=>router.push('/login'))">退出</button></div></header><div class="supply-layout"><aside class="supply-sidebar"><WorkspaceNav/><div class="supply-identity"><template v-if="independent"><p>独立商单核验与榜单</p><p class="muted">写入需服务器授权 GIG_REVIEW；不携带经营主体，也不能自行授予权限。</p></template><template v-else><label>当前办理身份<select data-testid="gigs-party" :value="session.selectedId" :disabled="locked" @change="session.selectParty(($event.target as HTMLSelectElement).value)"><option v-for="p in session.parties" :key="p.party.id" :value="p.party.id">{{p.party.display_name}}</option></select></label><p class="muted">{{canOwn?'有效负责人身份':'商业办理需有效负责人身份'}}</p></template></div></aside><main class="supply-main"><div class="supply-heading"><div><h1>{{pageTitle}}</h1><p>{{reviewPage?'依据保存的条款和实际外部材料独立作出决定。':'保存真实需求、商业协议与已核实交易事实。'}}</p></div><button class="outline" :disabled="locked||pageLoading" @click="loadPage">刷新当前记录</button></div><div class="loaded-tabs"><RouterLink v-for="s in (reviewPage?['requests','offers','rules']:['catalogue','offers','relations','commissions','rankings'])" :key="s" :to="`/gigs/${reviewPage?'reviews/':''}${s}`" :class="{active:section===s}">{{{catalogue:'需求目录',requests:'需求审核',offers:reviewPage?'提案审核':'服务提案',relations:'直接合作',commissions:'佣金计提',rules:'规则审核',rankings:'真实榜单'}[s]}}</RouterLink></div><ApiErrorAlert :error="error"/><p v-if="notice" class="supply-notice" role="status">{{notice}}</p><div v-if="pending" class="supply-warning"><p>{{pending.command.label}}结果尚未确认。原内容、文件、版本与请求编号仍保留。</p><details><summary>查看原请求与已知结果编号</summary><p class="identifier">{{pending.key}}</p><p v-if="pending.resultId" class="identifier">{{pending.resultId}}</p></details><div class="supply-actions"><button class="outline" data-testid="gigs-recovery-check" :disabled="busy||now<retryAt" @click="ui.checkPending()">{{pending.resultId?'重新读取已知结果':'先核对原记录'}}</button><button v-if="!pending.resultId" class="primary" data-testid="gigs-recovery-retry" :disabled="busy||!pending.checked||now<retryAt" @click="ui.retry()">使用原编号重试</button></div></div><div v-if="changed" class="supply-warning"><label class="trade-check"><input v-model="newDecision" data-testid="gigs-conflict-confirm" type="checkbox">我已读取最新记录，将重新作出决定。</label></div><p v-if="initializing||pageLoading" class="supply-empty" role="status">正在读取当前身份与商业合作记录…</p><div v-else :key="route.fullPath+securityRevision">
<template v-if="formPage"><GigRuleForm v-if="section==='rules'" :disabled="formLocked" @submit="body=>create('rules',body,'RULE','登记规则版本')"/>
<form v-else-if="section==='requests'" class="trade-form" @submit.prevent="requestPayload&&create('requests',requestPayload,'GIG','提交商单需求')"><fieldset :disabled="formLocked"><section class="supply-card"><h2>需求标题与说明</h2><div class="trade-fields two"><label>需求标题 *<input v-model="requestForm.title" data-testid="gigs-title" maxlength="200" required></label><label>完整需求说明 *<textarea v-model="requestForm.brief" data-testid="gigs-brief" maxlength="8000" required></textarea></label></div></section><section class="supply-card"><h2>采用规则、类别与商业范围</h2><div class="trade-fields three"><label>已生效规则 *<select v-model="requestForm.rule" data-testid="gigs-rule" required><option value="">请选择实际规则</option><option v-for="r in catalogue?.rules" :key="r.id" :value="r.id">{{r.rule.version}} · {{r.id}}</option></select></label><label>需求类别 *<select v-model="requestForm.category" data-testid="gigs-category" required><option value="">待选择</option><option v-for="c in chosenRule?.rule.categories" :key="c.code" :value="c.code" :disabled="!c.allowed">{{c.code}}{{c.allowed?'':'（禁止）'}}</option></select></label><label>用途<input value="商业用途 COMMERCIAL" readonly></label><label>地域 *<input v-model="requestForm.territory" data-testid="gigs-territory" maxlength="128" required></label><label>有效截止 *<input v-model="requestForm.until" data-testid="gigs-until" type="datetime-local" required></label></div><details v-if="chosenRule" class="trade-rules"><summary>查看所选完整规则与证明要求</summary><p class="long-text">{{chosenRule.rule.terms}}</p><p>当前类别证明：{{chosenCategory?.required_proofs.join('、')||'无必需证明'}}</p></details></section><section class="supply-card"><div class="section-heading"><h2>逐项私有证明</h2><button type="button" class="outline" :disabled="requestForm.proofs.length>=30" @click="requestForm.proofs.push({code:'',asset_id:''})">添加证明</button></div><div v-for="(p,n) in requestForm.proofs" :key="n" class="trade-row"><div class="trade-fields two"><label>证明代码 *<input v-model="p.code" :data-testid="`gigs-proof-code-${n}`" required maxlength="128"></label><label>已上传私有材料编号 *<input v-model="p.asset_id" :data-testid="`gigs-proof-asset-${n}`" required></label></div><SupplyUpload :key="securityRevision" :label="`商单证明${n+1}`" :ids="p.asset_id?[p.asset_id]:[]" single :disabled="formLocked" @upload="(file,type)=>upload(file,type,n)" @remove="p.asset_id=''"/><button type="button" class="danger" @click="requestForm.proofs.splice(n,1)">移除此证明</button></div><p v-if="!requestForm.proofs.length" class="muted">所选类别可无必需证明；额外证据可显式添加。引用仍由服务器核对归属、用途与内容完整性。</p></section><section class="supply-card"><h2>提交与发布</h2><p class="muted">登记后等待独立审核。只有发布状态且未暂停、未到期的商单进入真实目录。</p><button class="primary" data-testid="gigs-submit" :disabled="formLocked||!requestPayload">提交商单需求</button></section></fieldset></form>
<form v-else-if="section==='offers'" class="trade-form" @submit.prevent="offerPayload&&create('offers',offerPayload,'OFFER','提交商单服务提案')"><fieldset :disabled="formLocked"><section class="supply-card"><h2>实际商单与本人服务规格</h2><div class="trade-fields two"><label>已发布商单 *<select v-model="offerForm.gig" data-testid="gigs-gig" required><option value="">选择实际商单</option><option v-for="g in catalogue?.items.filter(g=>g.buyer_party_id!==session.selectedId)" :key="g.id" :value="g.id">{{g.title}} · {{g.category}}</option></select></label><label>本人已发布服务规格 *<select v-model="offerForm.spec" data-testid="gigs-spec" required><option value="">选择已审规格</option><option v-for="s in specs.filter(s=>s.kind==='SPEC'&&s.current_status==='PUBLISHED'&&s.merchant_party_id===session.selectedId&&s.data.provider_party_id===session.selectedId&&s.data.line_kind!=='LICENSE')" :key="s.id" :value="s.id">{{s.kind==='SPEC'?s.data.title+' · '+money(s.data.unit_minor):s.id}}</option></select></label></div><template v-if="chosenGig"><p class="long-text">{{chosenGig.brief}}</p><p class="gigs-scope">商业用途 · {{chosenGig.scope.territory}} · {{chosenGig.scope.valid_until}}</p></template><p class="muted">本页不设置成交价格。确认提案后，原报价仍须明确选择服务、数量、分期与支付条件。</p></section><section class="supply-card"><h2>本人数字人与已审商业脸声同意</h2><div class="trade-fields two"><label>本人登记数字人 *<select v-model="offerForm.avatar" data-testid="gigs-avatar" required><option value="">选择实际数字人</option><option v-for="a in avatars" :key="a.id" :value="a.id">{{a.data.display_name}} · {{a.id}}</option></select></label><label>已独立审核的本人商业脸声同意 *<select v-model="offerForm.consent" data-testid="gigs-consent" required><option value="">选择当前可用同意记录</option><option v-for="c in eligibleConsents" :key="c.id" :value="c.id">{{c.id}} · {{c.data.consent?.valid_until}}</option></select></label></div><details v-if="chosenConsent?.data.consent" class="trade-rules"><summary>查看本人同意原范围与条款</summary><p>{{chosenConsent.data.consent.features.join('、')}} · {{chosenConsent.data.consent.purposes.join('、')}} · {{chosenConsent.data.consent.territories.join('、')}}</p><p>{{chosenConsent.data.consent.valid_from}} 至 {{chosenConsent.data.consent.valid_until}}</p><p class="long-text">{{chosenConsent.data.consent.terms}}</p></details><p class="supply-warning">要求本人 FACE 与 VOICE 的商业用途同意，地域与有效期覆盖需求。登记数字人不代表已完成实名或水印核验。</p></section><section class="supply-card"><h2>直接 MCN 关系与精确分成</h2><label>本次直接合作安排 *<select v-model="offerForm.relation" data-testid="gigs-relation" required><option value="">明确选择</option><option value="NONE">不关联 MCN（MCN 费率须填写零）</option><option v-for="r in relations.filter(r=>r.kind==='RELATION'&&r.current_status==='ACTIVE'&&r.counterparty_id===session.selectedId)" :key="r.id" :value="r.id">{{r.id}} · {{r.owner_party_id}}</option></select></label><div class="trade-fields two"><label>平台费率（bps） *<input v-model="offerForm.platform" data-testid="gigs-platform-bps" inputmode="numeric" required placeholder="0–10000，明确填写"></label><label>MCN 费率（bps） *<input v-model="offerForm.mcn" data-testid="gigs-mcn-bps" inputmode="numeric" required placeholder="从平台费用内划分"></label></div><template v-if="chosenRelation?.kind==='RELATION'"><p>原合作费率：平台 {{chosenRelation.data.commission.platform_bps}} bps / MCN {{chosenRelation.data.commission.mcn_bps}} bps，填写值须完全一致。</p><p>{{chosenRelation.data.valid_from}} 至 {{chosenRelation.data.valid_until}}</p><p class="long-text">{{chosenRelation.data.terms}}</p></template></section><section class="supply-card"><h2>原商业条款与排行选择</h2><label>完整服务提案条款 *<textarea v-model="offerForm.terms" data-testid="gigs-offer-terms" maxlength="8000" required></textarea></label><label>是否参加商业榜单 *<select v-model="offerForm.ranking" data-testid="gigs-ranking-opt-in" required><option value="">明确选择</option><option value="true">参加（仅已核实正式净实收交易）</option><option value="false">不参加</option></select></label></section><section class="supply-card"><h2>私有合作证据</h2><SupplyUpload :key="securityRevision" label="提案合作证明" :ids="offerForm.assets" :disabled="formLocked||offerForm.assets.length>=30" @upload="upload" @remove="id=>offerForm.assets=offerForm.assets.filter(x=>x!==id)"/><button class="primary" data-testid="gigs-submit" :disabled="formLocked||!offerPayload">提交商单服务提案</button></section></fieldset></form>
<form v-else-if="section==='relations'" class="trade-form" @submit.prevent="relationPayload&&create('relations',relationPayload,'RELATION','发起直接MCN合作')"><fieldset :disabled="formLocked"><section class="supply-card"><h2>直接合作双方与实际能力</h2><p>{{canMcn?'当前主体具有有效 MCN 能力':'当前主体尚无有效 MCN 能力，不能发起合作。'}}</p><label>艺人本人主体编号 *<input v-model="relationForm.artist" data-testid="gigs-artist" required placeholder="由对方明确提供的真实主体编号"></label><p class="muted">无公开主体目录；此关系只连接当前 MCN 与艺人本人，不创建多级佣金网络。</p></section><section class="supply-card"><h2>商业范围、期限与排他安排</h2><div class="trade-fields three"><label>范围<input readonly value="商业用途 COMMERCIAL"></label><label>合作开始 *<input v-model="relationForm.from" data-testid="gigs-relation-from" type="datetime-local" required></label><label>合作截止 *<input v-model="relationForm.until" data-testid="gigs-relation-until" type="datetime-local" required></label><label>排他安排 *<select v-model="relationForm.exclusive" data-testid="gigs-exclusive" required><option value="">明确选择</option><option value="true">排他</option><option value="false">非排他</option></select></label></div></section><section class="supply-card"><h2>完整合作条款与费率</h2><label>双方完整合作条款 *<textarea v-model="relationForm.terms" data-testid="gigs-relation-terms" maxlength="8000" required></textarea></label><div class="trade-fields two"><label>平台费率（bps） *<input v-model="relationForm.platform" data-testid="gigs-platform-bps" required inputmode="numeric"></label><label>MCN 费率（bps） *<input v-model="relationForm.mcn" data-testid="gigs-mcn-bps" required inputmode="numeric"></label></div><p class="muted">0–10000 bps，1 bps = 0.01%。MCN 费率不得高于平台费率，从平台费用中划分。</p></section><section class="supply-card"><h2>私有原始证据与发起</h2><SupplyUpload :key="securityRevision" label="直接合作证明" :ids="relationForm.assets" :disabled="formLocked||relationForm.assets.length>=30" @upload="upload" @remove="id=>relationForm.assets=relationForm.assets.filter(x=>x!==id)"/><p class="muted">发起后待艺人本人负责人接受；有效 MCN 能力由服务器核验，不可在前端自批。</p><button class="primary" data-testid="gigs-submit" :disabled="formLocked||!relationPayload">发起直接MCN合作</button></section></fieldset></form></template>
<template v-else-if="section==='rankings'"><section class="supply-card"><h2>按生效规则生成真实快照</h2><form @submit.prevent="makeRanking"><fieldset :disabled="locked"><div class="trade-fields two"><label>已生效商单规则 *<select v-model="rankingRuleId" data-testid="gigs-ranking-rule" required><option value="">请选择实际规则</option><option v-for="r in catalogue?.rules" :key="r.id" :value="r.id">{{r.rule.version}} · {{r.id}}</option></select></label><label>快照截至日期（UTC 零时，完整历史日期） *<input v-model="asOf" data-testid="gigs-ranking-as-of" type="date" required></label></div><p class="muted">服务器只读取截止前已核实的正式商业净实收，保留采用规则；生成需独立 GIG_REVIEW 权限。此页面不表示已部署自动定时发布。</p><button class="primary" data-testid="gigs-ranking-create" :disabled="locked||!rankingRuleId||!rankingDate(asOf+'T00:00:00.000Z')">生成榜单快照</button></fieldset></form></section><section class="supply-card"><h2>读取已保存榜单</h2><div class="trade-fields two"><label>实际快照编号<input v-model="openId" data-testid="gigs-open-id" placeholder="完整快照编号"></label><button class="outline" :disabled="locked||!validSupplyId(openId)" @click="open">读取榜单快照</button></div><button class="outline" :disabled="locked" @click="ui.loadList('RANKING')">读取独立权限榜单记录</button><div v-for="r in rows.filter(r=>r.kind==='RANKING')" :key="r.id" class="trade-row"><RouterLink :to="`/gigs/rankings/${r.id}`">{{r.kind==='RANKING'?r.data.as_of:r.id}} · {{r.id}}</RouterLink></div></section><template v-if="ranking"><section class="supply-card"><h2>真实快照 · {{ranking.as_of}}</h2><p>{{ranking.data_status==='INSUFFICIENT_DATA'?'正式交易数据不足，当前没有可发布排名':'已按保存的规则生成正式交易排名'}}</p><p class="muted">三榜使用同一日期与规则版本。没有模拟数据；不公开订单和支付流水。</p><details class="trade-rules"><summary>查看保存的榜单规则参数</summary><p class="identifier">{{ranking.rule_id}}</p><ContractText :value="savedText(ranking.rule)" :field-labels="{window_days:'观察窗口（天）',newcomer_days:'新人观察期（天）',minimum_orders:'最低订单数',order_weight:'订单权重',net_minor_weight:'净实收权重',newcomer_bonus:'新人加权'}"/></details></section><div class="gigs-board"><section v-for="(label,k) in {hot:'热度榜',emerging:'新秀榜',regional:'地域榜'}" :key="k" class="supply-card"><h3>{{label}}</h3><div v-if="ranking.boards[k].length" class="table-wrap"><table><thead><tr><th>主体与地域</th><th>订单数</th><th>分值</th></tr></thead><tbody><tr v-for="r in ranking.boards[k]" :key="r.party_id+'|'+r.territory"><td><span class="identifier">{{r.party_id}}</span><br>{{r.territory}}</td><td>{{r.orders}}</td><td>{{k==='emerging'?r.emerging:r.heat}}</td></tr></tbody></table></div><p v-else class="gigs-empty">正式交易数据不足</p></section></div></template><p v-else class="gigs-empty">输入已知快照编号或由独立人员生成后查看真实榜单。</p></template>
<template v-else-if="!targetId"><section v-if="section==='catalogue'" class="supply-card"><div class="section-heading"><h2>已发布且有效的需求</h2><RouterLink to="/gigs/requests/new" class="button-link primary">登记商单需求</RouterLink></div><div v-if="catalogue?.items.length" class="gigs-catalogue"><article v-for="g in catalogue.items" :key="g.id" class="trade-row"><h3>{{g.title}}</h3><p class="long-text">{{g.brief}}</p><p class="gigs-scope">{{g.category}} · 商业用途 · {{g.scope.territory}} · {{g.scope.valid_until}}</p><div class="supply-actions"><RouterLink :to="`/gigs/offers/new?gigId=${g.id}`" class="button-link outline">提交服务提案</RouterLink><RouterLink v-if="g.buyer_party_id===session.selectedId" :to="`/gigs/requests/${g.id}`" class="button-link outline">查看我的原始需求</RouterLink></div></article></div><p v-else class="gigs-empty">目前没有已发布且有效的需求。</p></section><section v-if="section==='commissions'" class="supply-card"><h2>按商业订单核算计提</h2><label>已关联提案的实际订单 *<select v-model="orderId" data-testid="gigs-order" :disabled="locked"><option value="">选择实际商业订单</option><option v-for="o in orders" :key="o.id" :value="o.id">{{o.id}} · {{o.kind==='ORDER'?money(o.data.financial.net_minor):''}}</option></select></label><button class="primary" data-testid="gigs-calculate" :disabled="locked||!orderId" @click="calculate">核算当前订单佣金</button><p class="supply-warning">核算为账务计提，不转账。累计退款重算后保存增减明细；出款、税务接口尚未开放。</p></section><div class="trade-list-actions"><RouterLink v-if="!reviewPage&&['offers','relations','rules','requests'].includes(section)" :to="`/gigs/${section}/new`" class="button-link primary">{{section==='offers'?'提交服务提案':section==='relations'?'发起直接MCN合作':section==='rules'?'登记规则版本':'登记商单需求'}}</RouterLink><RouterLink v-if="reviewPage&&section==='rules'" to="/gigs/rules/new" class="button-link outline">登记规则版本</RouterLink><label>已知记录编号<input v-model="openId" data-testid="gigs-open-id" placeholder="完整记录编号"></label><button class="outline" :disabled="locked||!validSupplyId(openId)" @click="open">打开已知记录</button></div><section class="supply-card"><h2>{{reviewPage?'可获准独立审核的记录':section==='catalogue'?'我的需求记录':'当前身份的真实记录'}}</h2><div v-if="rows.length" class="table-wrap"><table><thead><tr><th>保存内容</th><th>状态</th><th>记录版本</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{gigTitle(r)}}<div class="identifier">{{r.id}}</div></td><td>{{gigStatuses[r.current_status]||r.current_status}}</td><td>{{r.object_version}}</td><td><RouterLink :to="pathFor(r)" class="button-link table-link">打开记录</RouterLink></td></tr></tbody></table></div><p v-else class="gigs-empty">当前没有可读取记录。可使用完整编号读取已有获准记录。</p><button v-if="nextCursor" class="outline" :disabled="locked" @click="ui.loadList(kind,true)">加载下一页</button></section><section v-if="notifications.length" class="supply-card"><h2>我的真实状态通知</h2><p v-for="n in notifications" :key="n.id" class="identifier">{{n.event_code}} · {{n.record_id}}</p></section></template>
<template v-else-if="detail"><div :class="reviewPage?'review-layout':''"><div><GigRecordPanel :record="detail"/><section v-if="privateAssets.length" class="supply-card"><h2>保存的私有材料</h2><div v-for="a in privateAssets" :key="a.id+'|'+a.label" class="gigs-private-list trade-row"><span>{{a.label}}</span><span class="identifier">{{a.id}}</span><button class="outline" :disabled="locked" @click="ui.downloadEvidence(detail.id,a.id)">读取本记录私有证明</button></div><p class="muted">每次读取重新检查当前权限，服务器校验私有文件大小与 SHA-256。无公开地址替代。</p></section></div><section v-if="reviewPage" class="supply-card trade-review-form"><h2>独立审核意见</h2><form @submit.prevent="review"><fieldset :disabled="locked||!reviewable"><label>审核决定 *<select v-model="decision" data-testid="gigs-review-decision" required><option value="">明确选择</option><option value="APPROVED">批准</option><option value="REJECTED">拒绝</option></select></label><div v-if="detail.kind!=='RULE'&&decision==='APPROVED'" class="gigs-checks"><label v-for="(label,k) in checkLabels" :key="k" class="trade-check"><input v-model="checks[k]" :data-testid="`gigs-check-${k}`" type="checkbox">{{label}}</label></div><label>实际核验理由 *<textarea v-model="reason" data-testid="gigs-review-reason" maxlength="2000" required></textarea></label><button class="primary" data-testid="gigs-review-submit" :disabled="locked||!reviewValid">提交独立审核</button></fieldset></form><p class="muted">创建者及参与方不可自审。勾选记录实际完成的外部核验，不表示平台自动完成实名、水印或权属审核。</p><template v-if="detail.kind==='GIG'&&detail.current_status==='PUBLISHED'||detail.kind==='RULE'&&detail.current_status==='EFFECTIVE'"><h3>{{detail.kind==='RULE'?'退役此规则版本':'暂停商单发布'}}</h3><label>明确原因 *<textarea v-model="actionReason" data-testid="gigs-action-reason" :disabled="locked" maxlength="2000"></textarea></label><button class="outline danger" data-testid="gigs-action-submit" :disabled="locked||!actionReason.trim()" @click="action">{{detail.kind==='RULE'?'退役此规则版本':'暂停商单发布'}}</button><p class="muted">已保存的历史商业协议与榜单保留当时版本。</p></template></section></div>
<section v-if="!reviewPage&&detail.kind==='OFFER'" class="supply-card"><h2>确认完整提案与履约关联</h2><label class="trade-check"><input v-model="confirmed" data-testid="gigs-accept-confirm" type="checkbox" :disabled="locked||detail.current_status!=='APPROVED'||detail.counterparty_id!==session.selectedId">我已核对当前提案、本人脸声商业范围、原 MCN 关系、精确费率和完整条款。</label><div class="supply-actions"><button class="primary" data-testid="gigs-accept" :disabled="locked||!acceptanceValid" @click="accept">确认当前完整提案</button><RouterLink v-if="detail.current_status==='ACCEPTED'&&detail.owner_party_id===session.selectedId&&!quotes.length" :to="`/trade/offers/${detail.id}/quote`" class="button-link primary">按原提案建立明确报价</RouterLink></div><p class="muted">原样提交当前完整内容指纹；确认提案不等于订单、付款或数字人已获永久授权。</p><h3>真实报价与订单关联</h3><p v-if="!quotes.length" class="muted">尚无已加载关联报价。供给方确认后可在原交易流程明确填写报价。</p><div v-for="q in quotes" :key="q.id" class="trade-row"><RouterLink :to="`/trade/quotes/${q.id}`">查看保存的原报价</RouterLink><RouterLink v-if="q.kind==='QUOTE'&&q.data.order_id" :to="`/trade/orders/${q.data.order_id}`" class="button-link outline">查看已有订单</RouterLink></div><RouterLink to="/gigs/commissions" class="button-link outline">查看订单佣金计提</RouterLink></section>
<section v-if="!reviewPage&&detail.kind==='RELATION'" class="supply-card"><h2>本人确认、拒绝或结束</h2><form @submit.prevent="relationAct"><fieldset :disabled="locked||!relationChoices.length"><div class="trade-fields two"><label>本次决定 *<select v-model="relationDecision" data-testid="gigs-relation-decision" required><option value="">明确选择</option><option v-for="v in relationChoices" :key="v" :value="v">{{v==='ACCEPT'?'接受原合作条款':v==='REJECT'?'拒绝邀请':'结束此直接合作'}}</option></select></label><label>本次理由 *<textarea v-model="relationReason" data-testid="gigs-relation-reason" maxlength="2000" required></textarea></label></div><button class="primary" data-testid="gigs-relation-submit" :disabled="locked||!relationChoices.includes(relationDecision)||!relationReason.trim()">提交本人合作决定</button></fieldset></form><p class="supply-warning">接受需艺人本人有效负责人身份。结束关系阻止新的采用，已成交订单继续使用保存的原佣金条款。</p></section>
<section v-if="detail.kind==='COMMISSION'" class="supply-card"><div class="section-heading"><h2>逐版本增减计提记录</h2><button class="outline" data-testid="gigs-recalculate" :disabled="locked" @click="orderId=detail.data.order_id;calculate()">按当前收款退款重新核算</button></div><div v-if="entries.length" class="table-wrap"><table><thead><tr><th>记录版本</th><th>供应方增减</th><th>平台增减</th><th>MCN 增减</th><th>当时净实收</th></tr></thead><tbody><tr v-for="e in entries" :key="e.id"><td>{{e.object_version}}</td><td>{{e.data.delta.supplier_minor<0?'−':''}}{{money(Math.abs(e.data.delta.supplier_minor))}}</td><td>{{e.data.delta.platform_minor<0?'−':''}}{{money(Math.abs(e.data.delta.platform_minor))}}</td><td>{{e.data.delta.mcn_minor<0?'−':''}}{{money(Math.abs(e.data.delta.mcn_minor))}}</td><td>{{money(e.data.facts.net_minor)}}</td></tr></tbody></table></div><p v-else class="gigs-empty">尚未读取计提明细。</p><div class="supply-actions"><RouterLink v-if="detail.owner_party_id===session.selectedId||detail.counterparty_id===session.selectedId" :to="`/trade/orders/${detail.data.order_id}`" class="button-link outline">核对原订单与付款退款</RouterLink><button disabled>出款与税务尚未开放</button><p v-if="detail.owner_party_id!==session.selectedId&&detail.counterparty_id!==session.selectedId" class="muted">MCN 可按历史协议读取与重算此计提；原交易订单仅向买卖方开放。</p></div></section>
<div class="trade-footer"><RouterLink :to="`/gigs/${reviewPage?'reviews/':''}${section}`" class="button-link outline">返回真实记录列表</RouterLink></div></template><p v-else class="gigs-empty">未读取到当前记录，请核对记录编号与权限。</p>
</div></main></div></div></template>
